<ul><li><strong>&#1050;&#1072;&#1089;&#1089;&#1099; &#1089;&#1072;&#1084;&#1086;&#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;:</strong> &#1055;&#1086;&#1082;&#1091;&#1087;&#1072;&#1090;&#1077;&#1083;&#1080; &#1089;&#1082;&#1072;&#1085;&#1080;&#1088;&#1091;&#1102;&#1090; &#1080; &#1086;&#1087;&#1083;&#1072;&#1095;&#1080;&#1074;&#1072;&#1102;&#1090; &#1089;&#1072;&#1084;&#1080; &#8212; &#1089;&#1085;&#1080;&#1078;&#1077;&#1085;&#1080;&#1077; &#1088;&#1072;&#1089;&#1093;&#1086;&#1076;&#1086;&#1074; &#1085;&#1072; &#1087;&#1077;&#1088;&#1089;&#1086;&#1085;&#1072;&#1083; &#1085;&#1072; 60%.</li><li><strong>QR-&#1086;&#1087;&#1083;&#1072;&#1090;&#1072;:</strong> &#1052;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1072;&#1103; &#1086;&#1087;&#1083;&#1072;&#1090;&#1072;, &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; POS &#8212; &#1089;&#1085;&#1080;&#1078;&#1077;&#1085;&#1080;&#1077; &#1082;&#1086;&#1084;&#1080;&#1089;&#1089;&#1080;&#1081;.</li><li><strong>RFID-&#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072;:</strong> RFID-&#1084;&#1077;&#1090;&#1082;&#1080; &#1085;&#1072; &#1090;&#1086;&#1074;&#1072;&#1088;&#1072;&#1093; &#1076;&#1083;&#1103; &#1084;&#1075;&#1085;&#1086;&#1074;&#1077;&#1085;&#1085;&#1086;&#1081; &#1080;&#1085;&#1074;&#1077;&#1085;&#1090;&#1072;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;, &#1079;&#1072;&#1097;&#1080;&#1090;&#1099; &#1086;&#1090; &#1082;&#1088;&#1072;&#1078; &#1080; &#1090;&#1088;&#1077;&#1082;&#1080;&#1085;&#1075;&#1072;.</li><li><strong>&#1055;&#1088;&#1077;&#1076;&#1086;&#1090;&#1074;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086;&#1090;&#1077;&#1088;&#1100; &#1089; &#1048;&#1048;:</strong> &#1050;&#1072;&#1084;&#1077;&#1088;&#1099; &#1080; &#1076;&#1072;&#1090;&#1095;&#1080;&#1082;&#1080; &#1076;&#1083;&#1103; &#1086;&#1073;&#1085;&#1072;&#1088;&#1091;&#1078;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1076;&#1086;&#1079;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1103; &#8212; &#1089;&#1085;&#1080;&#1078;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086;&#1090;&#1077;&#1088;&#1100;.</li></ul>
<div class="highlight-box"><p>&#128202; <strong>&#1044;&#1072;&#1085;&#1085;&#1099;&#1077; &#1086;&#1090;&#1088;&#1072;&#1089;&#1083;&#1080;:</strong> &#1059; &#1052;&#1057;&#1041; &#1089; &#1048;&#1048;: <strong>&#1089;&#1082;&#1083;&#1072;&#1076;&#1089;&#1082;&#1080;&#1077; &#1088;&#1072;&#1089;&#1093;&#1086;&#1076;&#1099; -32%</strong>, <strong>&#1091;&#1076;&#1086;&#1074;&#1083;&#1077;&#1090;&#1074;&#1086;&#1088;&#1105;&#1085;&#1085;&#1086;&#1089;&#1090;&#1100; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074; +28%</strong>, <strong>&#1074;&#1099;&#1088;&#1091;&#1095;&#1082;&#1072; +18%</strong>. &#1057;&#1088;&#1077;&#1076;&#1085;&#1080;&#1081; &#1089;&#1088;&#1086;&#1082; ROI: <strong>4-8 &#1084;&#1077;&#1089;&#1103;&#1094;&#1077;&#1074;</strong>.</p></div>

<h2>7. &#1056;&#1091;&#1082;&#1086;&#1074;&#1086;&#1076;&#1089;&#1090;&#1074;&#1086;: &#1040;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1088;&#1086;&#1079;&#1085;&#1080;&#1094;&#1099; &#1079;&#1072; 5 &#1096;&#1072;&#1075;&#1086;&#1074;</h2>
<ol><li><strong>&#1040;&#1085;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1091;&#1081;&#1090;&#1077; POS-&#1076;&#1072;&#1085;&#1085;&#1099;&#1077;:</strong> &#1054;&#1094;&#1077;&#1085;&#1080;&#1090;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1088;&#1086;&#1076;&#1072;&#1078; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1048;&#1048;-&#1072;&#1085;&#1072;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080;. &#1050;&#1072;&#1082;&#1080;&#1077; &#1090;&#1086;&#1074;&#1072;&#1088;&#1099;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1080; &#1089; &#1082;&#1072;&#1082;&#1086;&#1081; &#1084;&#1072;&#1088;&#1078;&#1086;&#1081;?</li><li><strong>&#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1077; &#1087;&#1088;&#1086;&#1075;&#1085;&#1086;&#1079;:</strong> &#1053;&#1072;&#1095;&#1085;&#1080;&#1090;&#1077; &#1048;&#1048;-&#1087;&#1088;&#1086;&#1075;&#1085;&#1086;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; &#1058;&#1086;&#1087;-20 &#1090;&#1086;&#1074;&#1072;&#1088;&#1086;&#1074;. &#1053;&#1072; 30% &#1084;&#1077;&#1085;&#1100;&#1096;&#1077; &#1080;&#1079;&#1083;&#1080;&#1096;&#1082;&#1086;&#1074; &#1079;&#1072; 3 &#1084;&#1077;&#1089;&#1103;&#1094;&#1072;.</li><li><strong>&#1057;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072;&#1094;&#1080;&#1103; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074;:</strong> &#1056;&#1072;&#1079;&#1076;&#1077;&#1083;&#1080;&#1090;&#1077; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074; &#1087;&#1086; &#1080;&#1089;&#1090;&#1086;&#1088;&#1080;&#1080; &#1087;&#1086;&#1082;&#1091;&#1087;&#1086;&#1082; &#1080; &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1077; &#1087;&#1077;&#1088;&#1089;&#1086;&#1085;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1077; &#1082;&#1072;&#1084;&#1087;&#1072;&#1085;&#1080;&#1080;.</li><li><strong>&#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1077; &#1086;&#1084;&#1085;&#108